class ExplorerShip {
    constructor(shipName) {
        this.shipName = shipName;
        // TODO: This class is doing too much!
        // It's responsible for navigation, combat, and communications.
        // Refactor these responsibilities into separate, dedicated classes.
        // Then, compose the ExplorerShip using instances of those classes.
    }

    moveToCoordinates(x, y, z) {
        console.log(`${this.shipName} navigating to [${x}, ${y}, ${z}]...`);
        // Simulates complex navigation logic
        return `Arrived at Sector ${x}-${y}-${z}.`;
    }

    shootPhotonTorpedos(target) {
        console.log(`${this.shipName} targeting ${target} with photon torpedos!`);
        // Simulates weapon firing sequence
        return `Engaged ${target}. Torpedos launched!`;
    }

    hailStarfleet(message) {
        console.log(`${this.shipName} attempting to hail Starfleet with message: "${message}"`);
        // Simulates communication protocols
        return `Message "${message}" transmitted to Starfleet.`;
    }
}

// Example usage (will need to be updated after refactoring)
const valiant = new ExplorerShip("Valiant");
console.log(valiant.moveToCoordinates(100, 250, 50));
console.log(valiant.shootPhotonTorpedos("Klingon Bird-of-Prey"));
console.log(valiant.hailStarfleet("Need urgent assistance!"));

