class NavigationModule {
    navigate(shipName, x, y, z) {
        console.log(`${shipName} navigating to [${x}, ${y}, ${z}]...`);
        return `Arrived at Sector ${x}-${y}-${z}.`;
    }
}

class CombatModule {
    fireWeapon(shipName, target) {
        console.log(`${shipName} targeting ${target} with photon torpedos!`);
        return `Engaged ${target}. Torpedos launched!`;
    }
}

class CommsModule {
    transmitMessage(shipName, message) {
        console.log(`${shipName} attempting to hail Starfleet with message: "${message}"`);
        return `Message "${message}" transmitted to Starfleet.`;
    }
}

class ExplorerShip {
    constructor(shipName) {
        this.shipName = shipName;
        this.navigation = new NavigationModule();
        this.combat = new CombatModule();
        this.comms = new CommsModule();
    }

    moveToCoordinates(x, y, z) {
        return this.navigation.navigate(this.shipName, x, y, z);
    }

    shootPhotonTorpedos(target) {
        return this.combat.fireWeapon(this.shipName, target);
    }

    hailStarfleet(message) {
        return this.comms.transmitMessage(this.shipName, message);
    }
}

const valiant = new ExplorerShip("Valiant");
console.log(valiant.moveToCoordinates(100, 250, 50));
console.log(valiant.shootPhotonTorpedos("Klingon Bird-of-Prey"));
console.log(valiant.hailStarfleet("Need urgent assistance!"));

